\begin{definition}
\label{def:homomorphism}
Let $G$ and $H$ be groups. A \emph{homomorphism} from $G$ to $H$ is a function $\phi:G\to H$ such that $\phi(g_1g_2)=\phi(g_1)\phi(g_2)$ for all $g_1,g_2\in G$.
\end{definition}

\begin{definition}
\label{def:isomorphism}
Let $G$ and $H$ be groups. A \emph{homomorphism} from $G$ to $H$ is an \emph{isomorphism} if it is bijective and its inverse is also a homomorphism.
\end{definition}

\begin{definition}
\label{def:subgroup}
Let $G$ be a group. A \emph{subgroup} of $G$ is a non-empty subset $H$ of $G$ such that $H$ is a group under the operation of $G$.
\end{definition}

\begin{definition}
\label{def:normal_subgroup}
Let $G$ be a group. A \emph{normal subgroup} of $G$ is a subgroup $H$ of $G$ such that $gH=Hg$ for all $g\in G$.
\end{definition}

\begin{definition}
\label{def:quotient_group}
Let $G$ be a group and $H$ a normal subgroup of $G$. The \emph{quotient group} $G/H$ is the set of all left cosets of $H$ in $G$, with the operation defined by $(gH)+(hH)=(gh)H$ for all $g,h\in G$.
\end{definition}

